package fundamentals;

public class DisplayNumber {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
	for (int a=10;a<=20;a++) {
			
			
			System.out.println(a);
		}
		
		for (int i=10;i<=20;i++) {
			
			if(i%2==0)
			System.out.println("Even number"+ i);
		}

	}

}
